 "content": "def transform(grid):
    """Extend the row and column of every colored plus center, filling blanks.

    The colored center lines cross other pluses, but the 3 markers and
    nonzero centers remain unchanged. This matches each demonstration pair.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    for r, c, color in centers:
        for j in range(w):
            if grid[r][j] == 0:
                out[r][j] = color
        for i in range(h):
            if grid[i][c] == 0:
                out[i][c] = color
    return out
